public partial class MigrationScene {
 async Task FeverStoryChecks(){await LivingWorldChecks();}
 async void CaptureFeverStory(){try{feverFixture=true;game.World.Changes.FeverStory=new();ClearEnemies();game.World.Changes.Time=980;Teleport(game.World.RouteX(FeverMeetZ)+7,FeverMeetZ);SpawnFeverStory();TickFeverStory(.1);paused=false;weaponRoot.Visible=false;camera.GlobalPosition=FeverBoyPoint+new Vector3(1,1.5f,3.5f);camera.LookAt(FeverBoyPoint+Vector3.Up*.75f);await ArtShot("fever-01-request");
  player.Position=FeverPoint(0,.1f,6);camera.GlobalPosition=FeverPoint(-10,4,17);camera.LookAt(FeverPoint(0,1.6f,1));await ArtShot("fever-02-house");
  Fever.Stage=3;SetFeverBoy(FeverPoint(.8f,.06f,2.4f));FeverSay("NOAH: She's on the sofa. Please look at her. I'll stay right here.");DrawFeverStory(.1);player.Position=FeverPoint(0,.1f,3.7f);camera.Position=new(0,1.65f,0);camera.LookAt(FeverPoint(-1.4f,1,-.3f));await ArtShot("fever-03-sister-and-door");
  Fever.Stage=5;Fever.Choice="open";Fever.Line="";Fever.LineTime=0;SpawnFeverMother();DrawFeverStory(.1);camera.LookAt(FeverPoint(0,1,-1.2f));await ArtShot("fever-04-breach");ShowFeverNotebook(true);await ArtShot("fever-05-notebook");GetTree().Quit();}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}

 int feverCheckAck;
 [Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFeverAck(int stage){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))feverCheckAck=Math.Max(feverCheckAck,stage);}
 async Task FeverCoopChecks(CoopActor a){feverFixture=true;game.World.Changes.FeverStory=new();var home=HostPosition;ClearEnemies();Teleport(game.World.RouteX(FeverMeetZ)+7,FeverMeetZ);SpawnFeverStory();TickFeverStory(.1);a.Body.Position=FeverBoyPoint+Vector3.Right;SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);FeverSync();RpcId(a.Id,nameof(CoopCheckStage),"fever-accept",a.Body.Position);await CoopWait(()=>feverCheckAck>=1,"Guest could not accept fever mission",15);if(Fever.Owner!=a.Identity||Fever.GivenName!=a.Name)throw new Exception("Fever escort identity/disclosed name assigned to wrong player");
  Fever.Waypoint=5;SetFeverBoy(FeverPoint(.8f,.06f,2.4f));FeverStage(3,"Please check his sister.");a.Body.Position=FeverPoint(-1.7f,.1f,1.4f);a.Game.Shield=40;int hostBandages=game.Life.Bandages,guestBandages=a.Game.Life.Bandages;SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);RpcId(a.Id,nameof(CoopCheckStage),"fever-tend",a.Body.Position);await CoopWait(()=>feverCheckAck>=2,"Guest breach did not replicate",15);await CoopWait(()=>Fever.Stage==5,"Fever cinematic did not finish",8);if(hostBandages!=game.Life.Bandages||guestBandages!=a.Game.Life.Bandages)throw new Exception("Fever inspection consumed medicine");var frame=Json.Read<CoopFrame>(Json.Write(FrameFor(a.Body.Position)));if(frame.Fever.Stage!=5||frame.Fever.Waypoint!=5)throw new Exception("Fever state missing from movement snapshot");KillEnemy(infected.Single(e=>e.Id==FeverMotherId));TickFeverStory(.1);a.Body.Position=FeverPoint(2.4f,.1f,2.5f);SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);FeverSync();RpcId(a.Id,nameof(CoopCheckStage),"fever-notebook",a.Body.Position);await CoopWait(()=>feverCheckAck>=3,"Guest aftermath notebook missing",15);if(paused||!a.Game.Profile.Journal.Seen.Contains(FeverJournal)||game.Profile.Journal.Seen.Contains(FeverJournal))throw new Exception("Fever notebook affected host UI/profile");feverFixture=false;Teleport(home.X,home.Z);a.Body.Position=HostPosition+Vector3.Right*3;SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);GD.Print("PASS / two-process fever quest: guest escort ownership, breach replication, shared fight, personal journal UI and inventory conservation");
 }
 async Task ClientFeverChecks(string stage,Vector3 target){feverFixture=true;await CoopWait(()=>Distance(player.Position,target)<1,"Fever test teleport missing",15);SpawnFeverStory();if(stage=="fever-accept"){await CoopWait(()=>Fever.Stage==1&&GodotObject.IsInstanceValid(feverBoy),"Fever boy replica missing");CoopRequest("fever","accept");await CoopWait(()=>Fever.Stage==2,"Fever acceptance missing");RpcId(1,nameof(CoopFeverAck),1);}else if(stage=="fever-tend"){await CoopWait(()=>Fever.Stage==3,"Fever house stage missing");CoopRequest("fever","tend");await CoopWait(()=>Fever.BiteKnown&&Fever.Stage==3,"Optional bite clue missing");CoopRequest("fever","truth");await CoopWait(()=>Fever.Stage==5,"Chosen confrontation missing");RpcId(1,nameof(CoopFeverAck),2);}else if(stage=="fever-notebook"){await CoopWait(()=>Fever.Stage==9,"Fever flight resolution missing");CoopRequest("fever","notebook");await CoopWait(()=>paused&&game.Profile.Journal.Seen.Contains(FeverJournal),"Guest fever notebook UI/save missing");CloseMenu();RpcId(1,nameof(CoopFeverAck),3);feverFixture=false;}}
}
